function ruleTargetSelfManagesLabel(rule) {
    var addLabels = normalizeLabels(rule.addLabel, rule.addLabels);
    if (!addLabels.length || !rule.configFile) return false;
    try {
        var raw = file_read({ path: rule.configFile });
