    if (issLs && issLs.indexOf(pl.blocker) !== -1) return 'blocker';
    if (prLs.indexOf(pl.low) !== -1 || (issLs && issLs.indexOf(pl.low) !== -1)) return 'low';
    return 'medium'; // no label anywhere — the default tier (label not required)
