function smRealKeyModules() {
    var shapes = loadModule('js/common/ticketKeyShapes.js', makeRequire({}), {});
    var trackers = loadModule('js/common/trackers.js', makeRequire({ '../config.js': configModule, './ticketKeyShapes.js': shapes }), {});
