    var key = (repoInfo.owner || '') + '/' + (repoInfo.repo || '') +
        ':issueLabels:' + issueNumber;
    var hit = _priorityIssueLabelCache.entries[key];
    if (hit) {
        if (Date.now() - hit.at > PRIORITY_ISSUE_LABEL_TTL_MS) {
