            var obj = (typeof res === 'string') ? parseMcp(res) : res;
            if (obj && typeof obj === 'object' && !obj.message) {
                labels = issueLabels(obj);
            }
        } catch (e) { labels = null; }
    }
    _priorityIssueLabelCache.entries[key] = { at: Date.now(), data: labels };
    return labels;
}

