{"content":"/**
 * reworkConsumption.js — fail-closed `agent:rework` consumption bookkeeping
 * and the consumed-without-work sweep decision (gh-840).
 *
 * Live pathology (dmtools-agents PR #826 / gh-825, 2026-10-10 ~10:00Z):
 * `agent:rework` was armed (twice, comments present) and later CONSUMED —
 * yet no rework leg ever ran, no fix commit landed on the head, 4/6 review
 * threads stayed unresolved and no closing bookkeeping comment existed.
 * Root cause: the PR-carrier rule's `consumeLabels` removes the label on
 * dispatch (or on the gh-715 cross-anchor suppression — any leg in flight
 * under the other anchor "fulfills" the request, even a REVIEW leg), with
 * nothing recording the consumption and nothing verifying a leg-close
 * marker. The armer that should have recovered (arm_rework /
 * rework-unresolved-threads) is withheld in this state (gh-806 latch,
 * gh-807 verdict gate, agent:review notLabels), so the arm never returned:
 * 4h+ hang.
 *
 * This module is the pure side of the fix:
 *
 *   Audit log  — every consumption posts ONE machine-parseable marker
 *                comment on the PR recording its path (dispatch |
 *                cross-anchor), the head sha and a timestamp. Markers are
 *                trusted only from machine identities (the same allowlist
 *                doctrine as reviewVerdicts.js — the format is public).
 *   Sweep      — shouldRestoreArm(): a PR with unresolved MACHINE review
 *                threads, no agent:rework label, no rework in flight,
 *                evidence of a prior consumption (consume/restore marker),
 *                the head NOT advanced past the consumed head (a real push
 *                is the close marker), quiet longer than staleMs (default
 *                30 min ≈ 6 ticks at a ~5-min cron) → restore the arm.
 *                Fail-closed everywhere: no evidence, no restore (AC3 —
 *                human-thread-only PRs are untouched); no clock, no
 *                restore.
 *
 * Pure module — no dmtools globals; smAgent feeds it comment payloads and
 * applies the decisions. GraalJS-clean (var + plain functions, JSON-safe
 * data only).
 */
'use strict';

// gh-840 AC1 bound: N ticks. The SM cron ticks every ~5 min; 30 min = 6
// ticks — the ticket's "≤6 ticks" self-heal bound. Deployment-tunable via
// the rule's staleMinutes knob (same shape as sweep_stale_validation).
var DEFAULT_RESTORE_STALE_MS = 30 * 60 * 1000;

// The consumption audit marker — one line, JSON payload, invisible in the
// rendered PR (same protocol family as the gh-807 verdict marker).
var CONSUME_MARKER_PREFIX = '<!-- dmtools:rework-consume ';
var RESTORE_MARKER_PREFIX = '<!-- dmtools:rework-restore ';
var MARKER_SUFFIX = ' -->';

// The only legal consumption paths (the guard vocabulary):
//   'dispatch'      — consumeLabels fired after an accepted workflow_dispatch
//   'cross-anchor'  — consumeLabels fired after the gh-715 cross-anchor
//                     suppression consumed the request
var CONSUME_PATHS = ['dispatch', 'cross-anchor'];

function isLegalConsumePath(path) {
    return CONSUME_PATHS.indexOf(path) !== -1;
}

/**
 * Builds the consumption-audit comment body. path must be one of
 * CONSUME_PATHS; headSha anchors the consumption to the head it was
 * supposed to rework (the sweep's close-proof check compares the recorded
 * head against the live head). Returns null on an unbuildable record —
 * callers skip the post; an unattributed consumption must never exist.
 */
function buildConsumeAuditComment(path, headSha, atIso) {
    if (!isLegalConsumePath(path)) return null;
    if (!headSha || typeof headSha !== 'string') return null;
    var payload = {
        path: path,
        head: headSha,
        at: atIso || new Date().toISOString()
    };
    return CONSUME_MARKER_PREFIX + JSON.stringify(payload) + MARKER_SUFFIX + '\n' +
        '🏷️ agent:rework consumed (path: ' + path + ', head ' +
        String(headSha).substring(0, 7) + ') — gh-840 consumption audit. ' +
        'The label must come off ONLY via a successful rework close; if no close ' +
        'follows, the tick sweep re-arms it.';
}

/**
 * Builds the sweep's restore bookkeeping marker (gh-821-style durability:
 * the next ticks read it as the newest quiet-window anchor, so a restore
 * whose arm is re-consumed without work re-enters the same bounded cycle
 * instead of being mistaken for fresh state).
 */
function buildRestoreMarkerComment(headSha, reason, atIso) {
    if (!headSha || typeof headSha !== 'string') return null;
    var payload = {
        head: headSha,
        reason: reason || 'restore',
        at: atIso || new Date().toISOString()
    };
    return RESTORE_MARKER_PREFIX + JSON.stringify(payload) + MARKER_SUFFIX + '\n' +
        '🔄 rework arm restored — previous consumption left threads unresolved (gh-840).';
}

function extractMarker(body, prefix) {
    var text = String(body || '');
    var start = text.indexOf(prefix);
    if (start === -1) return null;
    start += prefix.length;
    var end = text.indexOf(MARKER_SUFFIX, start);
    if (end === -1) return null;
    var raw = text.substring(start, end).trim();
    var parsed;
    try { parsed = JSON.parse(raw); } catch (e) { return null; }
    return (parsed && typeof parsed === 'object') ? parsed : null;
}

function commentAuthorLogin(item) {
    if (!item) return null;
    var u = item.user || item.author;
    if (!u) return null;
    var login = u.login || u.name;
    return login ? String(login).toLowerCase() : null;
}

/**
 * Marker list parser shared by consume/restore markers. comments: [{body,
 * user?|author?}] — opts.authorLogins, when a non-empty array, restricts to
 * machine identities (case-insensitive; forge hardening — the marker format
 * is public). Entries keep their payload order (comment streams arrive
 * chronological) and gain atMs (Date.parse of the embedded `at`, NaN when
 * unparsable — consumers must fail closed on NaN).
 */
function parseMarkers(comments, prefix, opts) {
    var list = Array.isArray(comments) ? comments : [];
    var allow = (opts && Array.isArray(opts.authorLogins) && opts.authorLogins.length)
        ? opts.authorLogins : null;
    var out = [];
    for (var i = 0; i < list.length; i++) {
        if (allow) {
            var who = commentAuthorLogin(list[i]);
            var trusted = false;
            for (var a = 0; a < allow.length; a++) {
                if (who && who === String(allow[a] || '').toLowerCase()) { trusted = true; break; }
            }
            if (!trusted) continue;
        }
        var rec = extractMarker(list[i] && list[i].body, prefix);
        if (!rec) continue;
        rec.atMs = Date.parse(rec.at || '');
        rec.order = i;
        out.push(rec);
    }
    return out;
}

function parseConsumeMarkers(comments, opts) {
    var out = parseMarkers(comments, CONSUME_MARKER_PREFIX, opts);
    // Only legal paths count — a forged/garbled path marker is not evidence.
    return out.filter(function (m) { return isLegalConsumePath(m.path); });
}

function parseRestoreMarkers(comments, opts) {
    return parseMarkers(comments, RESTORE_MARKER_PREFIX, opts);
}

/**
 * The sweep decision (pure — gh-840 AC1–AC3). state:
 *   unresolvedMachineThreads        — unresolved threads authored by the
 *                                     machine (the caller's census; >0 is
 *                                     the "threads to own" proof);
 *   hasReworkLabel                  — agent:rework present on the PR;
 *   reworkInFlight                  — gh-806 latch OR an active leg run on
 *                                     the head;
 *   consumedAtMs / restoredAtMs     — newest marker timestamps (null when
 *                                     no evidence exists);
 *   headAdvancedPastConsumption     — the live head differs from the newest
 *                                     consume marker's head (a push/refresh
 *                                     happened after the consumption — …

/**
 * reviewVerdicts.js — machine-parseable review-verdict records and their
 * reconciliation (gh-807).
 *
 * Live pathology (fa PR #1428, 2026-10-09 05:47:30Z + 05:47:40Z): two review
 * legs concluded on the SAME head 97 seconds apart with contradictory
 * verdicts; both side effects stuck (pr_approved + agent:rework coexisting)
 * and nothing ever reconciled them, because
 *   (a) verdicts were free-form comments with no head association — the
 *       headMovedSinceLastReview-style probes can never tie one to a head;
 *   (b) the SM tick had no verdict-reconciliation step;
 *   (c) the arming side (arm_rework) ignored the sticky-approval rule the
 *       rework side enforces (approved once → never re-review).
 *
 * The protocol: every review leg stamps ONE machine-parseable record on the
 * PR — a comment carrying the structured marker below. Everything else is
 * derived: newest record per head wins, a conflict WARNs (de-duplicated per
 * tick process), the loser label comes off with a comment citing both
 * verdict sources, and arming rework requires the effective verdict to not
 * be APPROVE — unless the record's own census reports open threads the
 * machine owns (blocking > 0, or suggestions > 0: the gh-683 conversation
 * gate would otherwise strand approve-with-suggestions PRs). Free-form
 * comment text is NEVER consulted — a comment that merely says
 * "REQUEST_CHANGES" without the marker does not exist for this module.
 * Records are trusted only from machine identities: the readers pass a
 * machineAuthor allowlist to parseVerdictRecords (gh-807 review round 3 —
 * a marker posted by any other identity is invisible, so a forged newer
 * record cannot steer arms, reconcile strips or query guards).
 *
 * One asymmetry (gh-807 review, BLOCKING thread): an APPROVE winner does
 * NOT invalidate every agent:rework arm. The label has non-review sources
 * that legitimately coexist with an APPROVE record on the SAME head —
 * red-CI rework on a sticky-approved PR (fail_validation), the sticky
 * dead-letter issue arm, conflict-rework on a DIRTY head, manual human
 * arms. The caller passes checksRed (the headHasRealFailure probe): a real
 * CI failure keeps the arm — the CI path owns the leg. Red CI never
 * legitimizes pr_approved, so a REQUEST_CHANGES/BLOCK winner always strips
 * it.
 *
 * Pure module — no dmtools globals; the tick actions and the query guards
 * feed it comment payloads and apply the decisions. Keep it GraalJS-clean
 * (var + plain functions, JSON-safe data only).
 *
 * gh-828: the withheld-arm branch's missing twin. APPROVE + blocking=0
 * withholds the rework arm — and nothing owned the machine's own open
 * suggestion threads, so the conversation gate (gh-683) held approved PRs
 * BLOCKED forever (live fa #1457–#1470, 2026-10-10). threadSeverity /
 * selectResolvableThreads / buildThreadAckReply are the pure side of the
 * in-tick post-APPROVE resolution leg (gate on the effective record,
 * resolve only machine-authored non-blocking threads, bounded).
 */
'use strict';

// The machine marker: one line, JSON payload, invisible in the rendered PR.
// Human-written or legacy comments never carry it — that is the point (AC4):
// verdict head-matching keys on the marker's structured head sha, not on
// comment text.
var MARKER_PREFIX = '<!-- dmtools:review-verdict ';
var MARKER_SUFFIX = ' -->';

// Verdicts the protocol admits. APPROVE is the sticky winner; the other two
// block pr_approved-gated paths until re-review.
var VERDICTS = ['APPROVE', 'REQUEST_CHANGES', 'BLOCK'];

// The two machine-owned carriers the reconciliation de-conflicts.
var LABEL_APPROVED = 'pr_approved';
var LABEL_REWORK = 'agent:rework';

/**
 * Builds the verdict-record comment body for a review leg to post.
 * record: { head, verdict, blocking, important, suggestions, at, source }
 *   head     — full head sha the verdict was rendered on (REQUIRED; a
 *              verdict without a head is the pathology this fixes)
 *   verdict  — APPROVE | REQUEST_CHANGES | BLOCK (the EFFECTIVE verdict
 *              after the leg's own overrides, not the raw LLM token)
 *   blocking/important/suggestions — the thread census (issueCounts)
 *   at       — ISO timestamp of the verdict
 *   source   — where the verdict came from (e.g. 'pr_review.json')
 * Returns null when the record is not postable (no head / no verdict) —
 * callers skip the post; a head-less record must never exist.
 */
function buildVerdictComment(record) {
    if (!record || !record.head || !record.verdict) return null;
    if (VERDICTS.indexOf(String(record.verdict).toUpperCase()) === -1) return null;
    var payload = {
        head: String(record.head),
        verdict: String(record.verdict).toUpperCase(),
        blocking: Number(record.blocking || 0) || 0,
        important: Number(record.important || 0) || 0,
        suggestions: Number(record.suggestions || 0) || 0,
        at: record.at || new Date().toISOString(),
        source: record.source || 'pr_review.json'
    };
    return MARKER_PREFIX + JSON.stringify(payload) + MARKER_SUFFIX + '\n' +
        '🤖 Review verdict record (gh-807) — machine-parsed by the SM tick to ' +
        'reconcile contradictory review legs on one head. Do not edit or reply.';
}

/**
 * Extracts one record from a comment body, or null. Only the marker counts.
 */
function extractVerdictRecord(body) {
    var text = String(body || '');
    var start = text.indexOf(MARKER_PREFIX);
    if (start === -1) return null;
    start += MARKER_PREFIX.length;
    var end = text.indexOf(MARKER_SUFFIX, start);
    if (end === -1) return null;
    var raw = text.substring(start, end).trim();
    var parsed;
    try { parsed = JSON.parse(raw); } catch (e) { return null; }
    if (!parsed || !parsed.head || !parsed.verdict) return null;
    var verdict = String(parsed.verdict).toUpperCase();
    if (VERDICTS.indexOf(verdict) === -1) return null;
    return {
        head: String(parsed.head),
        verdict: verdict,
