var EMPTY_LAP_MARKER_RE = /\uD83C\uDF00 empty rework lap (\d+)\/(\d+) \u2014 head ([0-9a-f]{7,40}) unchanged/g;

function emptyLapMaxOf(jobParams) {
    var n = (jobParams || {}).emptyLapMax;
    n = typeof n === 'string' ? parseInt(n, 10) : n;
