        sm.action(baseParams('epam', 'dmtools-agents', [sweepRule(30)], { machineAuthor: 'ai-teammate' }));
        assert.equal(sm.capturedPrLabelAdds.length, 0,
            'the sticky-approval semantics stand — verdict semantics are a non-goal');
